using System;
using System.Collections.Generic;

// PROGRAM: Mengamankan Kode dari Jebakan Edge Cases
public class FinancialStatistics
{
    // VERSI RENTAN BUG: Crash jika data kosong!
    public static decimal HitungRataRataRentan(List<decimal> transaksis)
    {
        decimal total = 0;
        foreach (var t in transaksis) total += t;
        return total / transaksis.Count; // DivideByZeroException jika Count == 0!
    }

    // VERSI ENTERPRISE (Tahan Uji Edge Cases):
    public static decimal HitungRataRataAman(List<decimal>? transaksis)
    {
        // 1. Guard edge case: null atau koleksi kosong
        if (transaksis == null || transaksis.Count == 0)
        {
            return 0m;
        }

        decimal total = 0;
        foreach (var t in transaksis)
        {
            total += t;
        }

        return total / transaksis.Count;
    }
}

public class Program
{
    public static void Main()
    {
        // Uji kasus batas kosong
        var dataKosong = new List<decimal>();
        Console.WriteLine($"Rata-rata aman data kosong: Rp {FinancialStatistics.HitungRataRataAman(dataKosong):N0}");
        Console.WriteLine($"Rata-rata aman data null: Rp {FinancialStatistics.HitungRataRataAman(null):N0}");
    }
}

