using System;
using System.Text;

public class PaymentParser
{
    public static long ParseNominalSafe(string? input)
    {
        if (string.IsNullOrWhiteSpace(input)) return 0;
        if (input.Contains('-')) return 0; // Edge case: tidak menerima nominal negatif

        var sb = new StringBuilder();
        foreach (char c in input)
        {
            if (char.IsDigit(c))
            {
                sb.Append(c);
            }
        }

        if (sb.Length == 0) return 0;

        return long.TryParse(sb.ToString(), out long result) ? result : 0;
    }

    public static void Main()
    {
        Console.WriteLine($"'Rp 150.000': {ParseNominalSafe("Rp 150.000")}");
        Console.WriteLine($"Null: {ParseNominalSafe(null)}");
        Console.WriteLine($"Negatif: {ParseNominalSafe("-5000")}");
    }
}
